<?php
namespace App\Console\Commands;
use App\Models\CustomerPortalToken;use App\Models\DataImport;use Illuminate\Console\Command;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;
class PrivacyMaintenance extends Command{protected$signature='privacy:cleanup';protected$description='Sletter utløpte tilgangsnøkler og midlertidige importfiler';public function handle():int{$tokens=CustomerPortalToken::where('expires_at','<',now()->subDays(30))->delete();$resets=DB::table('password_reset_tokens')->where('created_at','<',now()->subDay())->delete();$imports=0;DataImport::where('created_at','<',now()->subDays(30))->whereIn('status',['completed','failed'])->whereNotNull('stored_path')->where('stored_path','!=','')->each(function($import)use(&$imports){Storage::disk('local')->delete($import->stored_path);$import->update(['stored_path'=>'','preview'=>null]);$imports++;});$this->info("$tokens portaltokener, $resets passordnøkler og $imports importfiler ryddet.");return self::SUCCESS;}}
